using UnityEngine;

namespace Fireworks
{
    /// <summary>Maps cue types to prefabs and palette names to colours. Generated by Fireworks/Build All.</summary>
    [CreateAssetMenu(menuName = "Fireworks/Firework Library", fileName = "FireworkLibrary")]
    public class FireworkLibrary : ScriptableObject
    {
        [Tooltip("One prefab per FireworkType, in enum order (peony … fountain)")]
        public Firework[] prefabs = new Firework[FireworkCatalog.TypeCount];

        [Tooltip("Palette colours by name. HDR intensity comes from the particle materials.")]
        public PaletteColors[] palettes = Palettes.Defaults();

        public Firework Prefab(FireworkType type)
        {
            int i = (int)type;
            return prefabs != null && i < prefabs.Length ? prefabs[i] : null;
        }

        public PaletteColors Palette(string name)
        {
            if (palettes != null && !string.IsNullOrEmpty(name))
            {
                string key = name.Trim().ToLowerInvariant();
                foreach (var p in palettes)
                    if (p.name == key) return p;
            }
            if (palettes != null && palettes.Length > 0) return palettes[0];
            return Palettes.Defaults()[0];
        }
    }
}
